CREATE TABLE IF NOT EXISTS fee_categories (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS fee_discounts (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL, percent NUMERIC(5,2) NOT NULL CHECK (percent >=0 AND percent <=100), student_id BIGINT NULL REFERENCES students(id) ON DELETE CASCADE, category_id BIGINT NULL REFERENCES fee_categories(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS fee_fines (id BIGSERIAL PRIMARY KEY, invoice_id BIGINT NOT NULL REFERENCES invoices(id) ON DELETE CASCADE, amount_cents BIGINT NOT NULL CHECK (amount_cents>0), reason TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS receipts (id BIGSERIAL PRIMARY KEY, payment_id BIGINT NOT NULL REFERENCES payments(id) ON DELETE CASCADE, number TEXT NOT NULL UNIQUE, issued_at TIMESTAMPTZ NOT NULL DEFAULT now(), issued_by BIGINT NULL REFERENCES users(id) ON DELETE SET NULL);
ALTER TABLE invoices ADD COLUMN IF NOT EXISTS category_id BIGINT REFERENCES fee_categories(id) ON DELETE SET NULL;
ALTER TABLE invoices ADD COLUMN IF NOT EXISTS discount_cents BIGINT NOT NULL DEFAULT 0;
